  1→import { useState, useCallback, useEffect } from 'react';
  2→import { ThemeProvider } from './contexts/ThemeContext';
  3→import { useTheme } from './hooks/useTheme';
  4→import { useSessionId } from './hooks/useSessionId';
  5→import { LanguageProvider } from './contexts/LanguageContext';
  6→import { useTranslation } from './hooks/useTranslation';
  7→import { AgentProvider } from './contexts/AgentContext';
  8→import { ConfigProvider } from './contexts/ConfigContext';
  9→import { FileUpload } from './components/FileUpload';
 10→import { QueryEditor } from './components/QueryEditor';
 11→import { ResultsTable } from './components/ResultsTable';
 12→import { ResultMarkdown } from './components/ResultMarkdown';
 13→import { Sidebar } from './components/Sidebar';
 14→import { ErrorMessage } from './components/ErrorMessage';
 15→import { AgentPanel } from './components/AgentPanel';
 16→import type { TableInfo, QueryResult } from './types';
 17→import './App.css';
