115→function ErrorBlock({ errorMessage, onRetry }: { errorMessage: string; onRetry?: () => void }) {
116→  const { t } = useTranslation();
117→  return (
118→    <div className="message-bubble__segment message-bubble__segment--error">
119→      <div className="message-bubble__error-header">{t('errorOccurred')}</div>
120→      <div className="message-bubble__error-message">{errorMessage}</div>
121→      {onRetry && (
122→        <button className="message-bubble__error-retry" onClick={onRetry}>
123→          {t('tryAgain')}
124→        </button>
125→      )}
126→    </div>
127→  );
128→}
